package setura

import (
	"fmt"
	"io"
	"strings"
)

// roff escapes text for use in a man page body line.
func roff(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, "-", `\-`)
	if strings.HasPrefix(s, ".") || strings.HasPrefix(s, "'") {
		s = `\&` + s
	}
	return s
}

// Man writes the setura(1) manual page in roff, derived from the help groups
// so the page cannot drift from the command list.
func Man(w io.Writer) error {
	var cmds [][2]string
	for _, g := range helpGroups {
		for _, e := range g.entries {
			name := e.name
			if e.args != "" {
				name += " " + e.args
			}
			cmds = append(cmds, [2]string{name, e.summary})
		}
	}
	var b strings.Builder
	p := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	p(".TH SETURA 1 \"\" \"Zyvor Setura\" \"User Commands\"\n")
	p(".SH NAME\nsetura \\- serve, publish and verify Gateway API routes\n")
	p(".SH SYNOPSIS\n.B setura\n[\\fB\\-\\-context\\fR \\fINAME\\fR[,\\fINAME\\fR...] | \\fB\\-\\-all\\-contexts\\fR] \\fICOMMAND\\fR [\\fIflags\\fR]\n")
	p(".SH DESCRIPTION\n.B setura\nforwards Kubernetes Gateway API listeners to IPv4 loopback and verifies\nroutes from the client side.\n")
	p(".SH COMMANDS\n")
	for _, c := range cmds {
		p(".TP\n.B %s\n%s\n", roff(c[0]), roff(c[1]))
	}
	p(".PP\nRun \\fBsetura COMMAND \\-h\\fR for the flags of a command.\n")
	p(".SH MULTIPLE CONTEXTS\n\\fBcheck\\fR, \\fBsnapshot\\fR, \\fBgate\\fR and \\fBlint\\fR accept a comma separated list of kube contexts, or \\fB\\-\\-all\\-contexts\\fR, and merge the results with a per\\-context field. The exit status is unchanged.\n")
	p(".SH ALERTING\n\\fBsetura watch\\fR can post failure and recovery transitions with \\fB\\-\\-alert\\-webhook\\fR and \\fB\\-\\-alert\\-slack\\fR. The URLs are secrets and are never printed. \\fBsetura history\\fR summarizes the file written by \\fB\\-\\-history\\fR.\n")
	p(".SH ROUTING DECISIONS\n\\fBsetura why\\fR METHOD URL explains which listener, route, rule and backend the built\\-in gateway picks for a request and why every other candidate lost. It evaluates a gateway config (\\fB\\-\\-config\\fR, \\fB\\-\\-snapshot\\fR) or asks a running gateway (\\fB\\-\\-admin\\fR ADDR, endpoint /why) and sends no traffic. \\fB\\-H\\fR adds request headers, \\fB\\-\\-grpc\\fR service/method explains a gRPC call, \\fB\\-\\-sni\\fR host a TLSRoute connection, \\fB\\-\\-format\\fR json prints the trace. It also shows the trace headers and X\\-Forwarded\\-For the backend receives, the route's retry policy, the rate\\-limit bucket (\\fB\\-\\-rate\\-limit\\fR, \\fB\\-\\-rate\\-burst\\fR, \\fB\\-\\-rate\\-key\\fR model the gateway's policy offline, \\fB\\-\\-admin\\fR adds the live bucket) and mirrors with shadow\\-diff, and a file route's metadata.creationTimestamp breaks ties. It exits 0 when routed, 1 when no route matches and 2 on a usage error.\n.PP\n\\fBsetura replay\\fR reads the gateway's JSON and text access logs and Common or Combined Log Format (\\fB\\-\\-default\\-host\\fR supplies the Host those lack). Besides route, backend, outcome and weight changes it reports retry, timeout, mirror and rate\\-limit policy changes (\\fB\\-\\-before\\-rate\\-limit\\fR, \\fB\\-\\-after\\-rate\\-limit\\fR), flags backends that fail in the log, and replays gRPC calls and TLS passthrough connections through GRPCRoutes and TLSRoutes.\n")
	p(".SH GATEWAY TRAFFIC SECURITY\nThe built\\-in gateway can protect an HTTPRoute rule with an \\fBsetura.zyvor.dev/auth\\fR block (JWT, API key, basic auth, client address lists, required client certificate), validate client certificates on HTTPS listeners (Gateway API frontend TLS validation) and staple OCSP responses (\\fB\\-\\-ocsp\\-staple\\fR). \\fBsetura gateway hash\\fR \\fB\\-\\-kind\\fR apikey|password reads a secret on stdin and prints the hash to store. \\fB\\-\\-admin\\-token\\fR TOKEN (or SETURA_ADMIN_TOKEN) protects the admin endpoint and is required to bind it off loopback; \\fB\\-\\-admin\\-open\\-ready\\fR leaves /ready open. \\fBsetura why\\fR shows whether the credentials given with \\fB\\-H\\fR would pass. Credentials are redacted everywhere. See docs/security.md.\n.PP\nGRPCRoute rules take the same auth block; rejections are Trailers\\-Only gRPC statuses (UNAUTHENTICATED, PERMISSION_DENIED, RESOURCE_EXHAUSTED). \\fB\\-\\-client\\-allow\\-san\\fR and \\fB\\-\\-client\\-allow\\-cn\\fR (or a Gateway's \\fBsetura.zyvor.dev/client\\-allow\\fR annotation) restrict validated client certificates to named SANs or subject CNs, exact or *.suffix; refusals are logged and counted. \\fB\\-\\-client\\-cert\\-xfcc\\fR adds an Envoy\\-style X\\-Forwarded\\-Client\\-Cert header. A RequestHeaderModifier value may use {client_ip}, {request_id}, {host}, {scheme} and {listener}. \\fB\\-\\-access\\-log\\-exclude\\fR PATTERN and \\fB\\-\\-access\\-log\\-sample\\fR N keep requests out of the access log while they still count in metrics. See docs/client\\-cert\\-authz.md and docs/headers\\-and\\-logs.md.\n")
	p(".SH GATEWAY LIMITS AND RESPONSES\nA rule can answer without a backend with a \\fBsetura.zyvor.dev/direct\\-response\\fR block (status, body, headers), carry its own token bucket with \\fBsetura.zyvor.dev/rate\\-limit\\fR (rate, burst, key route|client\\-ip|header:NAME; the gateway\\-wide \\fB\\-\\-rate\\-limit\\fR still applies) and override the gateway limits with \\fBsetura.zyvor.dev/limits\\fR. \\fBsetura gateway run\\fR limits requests with \\fB\\-\\-max\\-request\\-body\\fR (413), \\fB\\-\\-max\\-header\\-bytes\\fR (431), \\fB\\-\\-header\\-read\\-timeout\\fR, \\fB\\-\\-idle\\-timeout\\fR and \\fB\\-\\-stream\\-idle\\-timeout\\fR, normalises paths before routing with \\fB\\-\\-normalize\\-path\\fR, \\fB\\-\\-merge\\-slashes\\fR and \\fB\\-\\-reject\\-escaped\\-slashes\\fR (all off by default) and bounds TLS with \\fB\\-\\-tls\\-min\\-version\\fR and \\fB\\-\\-tls\\-max\\-version\\fR. See docs/direct\\-response.md and docs/limits.md.\n")
	p(".SH REQUEST SHAPING, TRAFFIC SPLITS AND CORS\n\\fBsetura explain\\fR, check files and watch files can send \\fB\\-\\-method\\fR (GET, HEAD, OPTIONS; POST, PUT, PATCH and DELETE need \\fB\\-\\-allow\\-unsafe\\-method\\fR and carry no body) and repeated \\fB\\-\\-request\\-header\\fR \\(dqName: value\\(dq (check files: \\fBmethod\\fR, \\fBallow_unsafe_method\\fR, \\fBrequest_headers\\fR), so routes that match on method or header can be verified. Host and framing headers are refused, names and values are validated, and at most 32 headers and 16 KiB are sent. \\fBsetura split\\fR URL \\fB\\-\\-expect\\fR NAME=WEIGHT... sends \\fB\\-\\-requests\\fR (default 400, at most 20000) and compares the share each backend identity (header \\fB\\-\\-identity\\-header\\fR, default X\\-Setura\\-Backend) answered with the expected weights (proportional, like backendRef weights; 0 means none). It is a statistical check at 3.29 sigma: a correct split fails about once in a thousand runs per backend, an unexpected identity always fails, and it refuses a request count too small for the smallest share. \\fBsetura cors\\fR URL \\fB\\-\\-origin\\fR O sends the OPTIONS preflight a browser would send (\\fB\\-\\-request\\-method\\fR, \\fB\\-\\-request\\-headers\\fR, \\fB\\-\\-credentials\\fR) and judges status, Access\\-Control\\-Allow\\-Origin, Methods, Headers, Credentials, Max\\-Age and Vary against the Fetch standard. Both exit 0 on pass, 1 on a failed verdict and 2 on a usage error. See docs/probe-requests.md.\n")
	p(".SH API PLANS AND USAGE\n\\fBsetura gateway run \\-\\-plans\\fR FILE turns on API monetisation in the built\\-in gateway: a hot\\-reloaded JSON plan file defines named plans (requests per minute, day and month, a body byte quota, burst, allowed routes and methods, an optional price per 1000 requests, hard or soft enforcement) and maps API keys, JWT subjects, tenants or a trusted upstream header to a plan. Requests over a hard quota get 429 with Retry\\-After, a JSON body naming the quota and X\\-Quota\\-Limit, X\\-Quota\\-Remaining and X\\-Quota\\-Reset headers. Usage is metered per identity, route and plan, bounded in memory and persisted atomically with \\fB\\-\\-usage\\-state\\fR. \\fBsetura usage\\fR prints it (\\fB\\-\\-by\\fR key|route|plan|day, \\fB\\-\\-since\\fR, \\fB\\-\\-format\\fR table|json|csv); \\fBsetura usage invoice \\-\\-period\\fR YYYY\\-MM prices a month. \\fBsetura why \\-\\-plans\\fR FILE explains which plan and quota apply to a request and \\fBsetura lint \\-\\-plans\\fR FILE checks the file against the routes (SET020 to SET022). The gateway admin endpoint serves /usage, /usage.csv and /plans. Counters and quotas are per gateway replica: nothing is shared between replicas; see docs/metering-plans.md.\n")
	p(".SH GATEWAY TRAFFIC SECURITY\nThe built\\-in gateway can protect an HTTPRoute rule with an \\fBsetura.zyvor.dev/auth\\fR block (JWT, API key, basic auth, client address lists, required client certificate), validate client certificates on HTTPS listeners (Gateway API frontend TLS validation) and staple OCSP responses (\\fB\\-\\-ocsp\\-staple\\fR). \\fBsetura gateway hash\\fR \\fB\\-\\-kind\\fR apikey|password reads a secret on stdin and prints the hash to store. \\fB\\-\\-admin\\-token\\fR TOKEN (or SETURA_ADMIN_TOKEN) protects the admin endpoint and is required to bind it off loopback; \\fB\\-\\-admin\\-open\\-ready\\fR leaves /ready open. \\fBsetura why\\fR shows whether the credentials given with \\fB\\-H\\fR would pass. Credentials are redacted everywhere. See docs/security.md.\n")
	p(".SH AI GATEWAY\nA rule with a \\fBsetura.zyvor.dev/ai\\fR block (a rule field, or the route annotation of that name, or \\fBsetura.zyvor.dev/ai.rule\\-N\\fR) serves OpenAI\\-compatible \\fB/v1/chat/completions\\fR, \\fB/v1/completions\\fR and \\fB/v1/embeddings\\fR and Anthropic \\fB/v1/messages\\fR requests from a list of providers with weights and priorities. Provider API keys come from the environment, a file or a Kubernetes Secret and replace the client credential. The gateway counts prompt and completion tokens from the responses (JSON or the last SSE event) and reports them per route, provider, model and key in /metrics and in the access log (tokens_in, tokens_out, provider, model, cache_hit, cost_estimate). Token budgets per API key, JWT claim or tenant header (per minute, per day, per month) answer 429 with Retry\\-After before a request is forwarded. A 5xx, 429 or timeout moves the request to the next provider; the existing outlier ejection takes a failing provider out of rotation. An opt\\-in exact\\-match prompt cache and PII redaction (\\fBredact\\fR, \\fBblock\\fR or \\fBreport\\fR) are per route. \\fB\\-\\-ai\\-prices\\fR FILE supplies the price table for cost estimates and \\fB\\-\\-ai\\-max\\-key\\-labels\\fR N bounds metric label cardinality. \\fBsetura gateway ai\\-usage\\fR [\\fB\\-\\-admin\\fR ADDR] [\\fB\\-\\-route\\fR R] [\\fB\\-\\-key\\fR K] prints usage, budgets and provider health from the admin /ai/usage endpoint, and \\fBsetura why\\fR explains which provider a request would use and why. Lint rules SET040 to SET047 cover misconfigurations. See docs/ai\\-gateway.md.\n")
	p(".SH LOAD BALANCING AND EXTERNAL BACKENDS\nA rule picks the endpoint of its backend with a \\fBsetura.zyvor.dev/load\\-balancer\\fR block (a rule field, or the route annotation of that name, or \\fBsetura.zyvor.dev/load\\-balancer.rule\\-N\\fR); a backend can carry a \\fBloadBalancer\\fR block and \\fB\\-\\-load\\-balancer\\fR ALGO|JSON sets the gateway default. Algorithms: \\fBroundRobin\\fR (smooth, weighted, with an optional \\fBslowStart\\fR window for new endpoints), \\fBleastRequest\\fR (power of two choices on in\\-flight requests), \\fBrandom\\fR and \\fBconsistentHash\\fR (ring hash or Maglev on a header, a cookie the gateway sets when absent, the source IP or a query parameter). Endpoints carry a weight, a zone and a priority; \\fBlocality.preferLocalZone\\fR (with \\fB\\-\\-zone\\fR NAME, or SETURA_ZONE) keeps traffic in the local zone while enough of it is healthy, \\fBpriority.healthyPercent\\fR fails over from priority 0 to 1 and \\fBpanicThreshold\\fR ignores health when too few endpoints are healthy. Ejected and unhealthy endpoints are never picked unless every endpoint is. A backend may name hosts the gateway resolves itself and re\\-resolves on the DNS TTL (\\fB\\-\\-dns\\-ttl\\-min\\fR, \\fB\\-\\-dns\\-ttl\\-max\\fR; the last answer is kept when a lookup fails), plain IP:port addresses and unix sockets (unix:///run/app.sock). A Service\\-less backend is declared in the snapshot backends section or the \\fBsetura.zyvor.dev/backends\\fR route annotation and referenced with backendRef group setura.zyvor.dev, kind Backend. \\fBsetura why\\fR and the admin /status show the algorithm, the hash key and why an endpoint was chosen. Lint rules SET050 to SET053 cover misconfigurations. See docs/load\\-balancing.md.\n")
	p(".SH TRAFFIC SHAPING AND SHARED RATE LIMITS\nA \\fBsetura.zyvor.dev/rate\\-limit\\fR block with \\fBshared\\fR {\\fBredis\\fR, \\fBkeyPrefix\\fR, \\fBfailOpen\\fR} counts requests in Redis (a sliding window per client, MULTI/EXEC, no Lua) so the limit holds across replicas; \\fB\\-\\-redis\\fR [NAME=]ADDR names the server (also \\fB\\-\\-redis\\-password\\-file\\fR, \\fB\\-\\-redis\\-tls\\fR, \\fB\\-\\-redis\\-ca\\fR, \\fB\\-\\-redis\\-timeout\\fR, \\fB\\-\\-redis\\-pool\\fR). Answers carry X\\-RateLimit\\-Limit, \\-Remaining and \\-Reset; while Redis is down a per\\-replica bucket answers, or 503 with failOpen false. \\fB\\-\\-compress\\fR (with \\fB\\-\\-compress\\-types\\fR, \\fB\\-\\-compress\\-encodings\\fR, \\fB\\-\\-compress\\-min\\-size\\fR, \\fB\\-\\-compress\\-level\\fR) and the \\fBsetura.zyvor.dev/compress\\fR rule and listener block compress responses with gzip or deflate by Accept\\-Encoding; brotli and zstd are not in the Go standard library and are not offered. \\fB\\-\\-max\\-connections\\fR, \\fB\\-\\-max\\-connections\\-per\\-ip\\fR, \\fB\\-\\-tcp\\-keepalive\\-idle\\fR, \\fB\\-interval\\fR, \\fB\\-count\\fR, \\fB\\-\\-h2\\-max\\-streams\\fR, \\fB\\-\\-h2\\-initial\\-window\\fR, \\fB\\-\\-h2\\-max\\-frame\\-size\\fR, \\fB\\-\\-bandwidth\\-request\\fR, \\fB\\-\\-bandwidth\\-response\\fR (and a rule \\fBsetura.zyvor.dev/bandwidth\\fR block) and \\fB\\-\\-request\\-id\\fR preserve|generate|trust\\-upstream bound connections and pace transfers. A rule with \\fBsetura.zyvor.dev/grpc\\-web\\fR translates application/grpc\\-web and grpc\\-web\\-text calls from browsers to gRPC. HTTP/3 is not served. Lint rules SET070 to SET076. See docs/shared\\-rate\\-limits.md and docs/traffic\\-shaping.md.\n")
	p(".SH EXIT STATUS\n.TP\n.B 0\nsuccess\n.TP\n.B 1\nthe check, gate, lint, replay or migrate check failed or found differences, or why found no route\n.TP\n.B 2\nusage or input error\n")
	p(".SH GATEWAY ROLLOUT\n\\fBsetura gateway rollout\\fR lints a candidate snapshot, backs up the live file in \\fI.setura\\-history\\fR, replaces it atomically, waits for the admin /status generation, runs a checks file for an observation window and restores the backup on any failure. The window is judged on the probes and on the gateway's own /stats and /metrics deltas (\\fB\\-\\-max\\-error\\-rate\\fR and \\fB\\-\\-max\\-p95\\fR apply to both). A candidate that changes canary weights is applied in stages 10,50,100 unless \\fB\\-\\-steps\\fR or \\fB\\-\\-no\\-steps\\fR is given. A rollout lock left by a killed rollout (dead process on this host, or a heartbeat older than \\fB\\-\\-lock\\-timeout\\fR) is taken over; a live owner never is. Relative certificate paths resolve against the candidate's directory. \\fBsetura gateway history\\fR lists the backups and \\fBsetura gateway rollback\\fR restores one.\n")
	p(".SH GATEWAY INSTALL AND CLUSTER STATUS\n\\fBsetura gateway install\\fR prints plain YAML for the in\\-cluster controller and never applies it. \\fB\\-\\-service\\-type\\fR ClusterIP|NodePort|LoadBalancer, \\fB\\-\\-node\\-port\\fR HTTP=PORT,HTTPS=PORT, \\fB\\-\\-listener\\-port\\fR N (repeatable), \\fB\\-\\-external\\-traffic\\-policy\\fR, \\fB\\-\\-host\\-network\\fR, \\fB\\-\\-replicas\\fR, \\fB\\-\\-arg\\fR FLAG (repeatable), \\fB\\-\\-resources\\fR, \\fB\\-\\-node\\-selector\\fR and \\fB\\-\\-expose\\-gateway\\-ports\\fR remove the need to patch the output. The admin token Secret is not printed unless \\fB\\-\\-create\\-admin\\-secret\\fR is given, so re\\-applying never rotates the token; \\fB\\-\\-admin\\-token\\-secret\\fR NAME names an existing Secret. \\fB\\-\\-crds\\fR with \\fB\\-\\-gateway\\-api\\-version\\fR prints the command that installs the Gateway API CRDs. \\fBsetura gateway install \\-\\-check\\fR and \\fBsetura doctor gateway \\-\\-kube\\fR report missing or too old CRDs and which Setura feature needs which release. \\fBsetura gateway status\\fR lists Gateways and routes with Accepted, Programmed and ResolvedRefs and the reason. See docs/install\\-options.md and docs/cluster\\-troubleshooting.md.\n")
	p(".SH ENVOY GATEWAY COMPATIBILITY\n\\fBsetura gateway run \\-\\-kubernetes \\-\\-envoy\\-compat\\fR also reads Envoy Gateway's optional policy CRDs (BackendTrafficPolicy, ClientTrafficPolicy, SecurityPolicy, HTTPRouteFilter and Backend in gateway.envoyproxy.io/v1alpha1; absent CRDs are fine) and translates what Setura can express: retry, timeout, circuit breaker, active and passive health checks, load balancing (algorithm, consistent hash, slow start, zone preference), gzip compression, request body limits, local and Redis\\-backed global rate limits, fault injection, mirroring, TLS versions, cipher suites, session resumption and client validation with SAN allow\\-lists, connection limits, JWT, API key, OIDC login, authorization rules, credential injection, ExternalAuth, CORS, PROXY protocol to backends, direct responses and Backend endpoints. Targets (Gateway, listener, HTTPRoute, GRPCRoute, rule) follow Envoy Gateway precedence: the most specific wins, and mergeType StrategicMerge or JSONMerge merges over the less specific policy. Each policy gets Accepted, Conflicted and Overridden conditions; the reason Unsupported lists the fields Setura ignores, and a guard it cannot enforce (basicAuth, an OIDC policy without a cookie key) refuses the targeted traffic. \\fBsetura gateway install \\-\\-envoy\\-compat\\fR grants read and status access to those CRDs only. \\fBsetura migrate convert \\-\\-from envoy\\-gateway\\fR shares the translation, and \\fB\\-\\-compat\\-report\\fR lists every field with Supported, Partial or Unsupported. \\fBsetura gateway status\\fR and \\fBsetura doctor gateway \\-\\-kube\\fR list the policies and ignored fields; lint rules SET080 to SET083. See docs/envoy\\-compat.md and docs/envoy\\-gateway\\-compat.md.\n")
	p(".SH LICENCE\n\\fBsetura licence verify\\fR [KEY | \\fB\\-\\-file\\fR F] checks a signed ZYV1 licence key offline against the public keys embedded in the binary and prints the tier, cluster limit, expiry, licensee and status (valid, expired, bad signature, wrong product). \\fBsetura licence show\\fR checks the key in SETURA_LICENCE_KEY or the file named by SETURA_LICENCE_FILE (default: setura/licence.key in the user config directory). It exits 0 for a valid key, 1 for an invalid one and 2 on a usage error. Setura works without a key; \\fBsetura version \\-\\-verbose\\fR only reports the status and never blocks a command.\n")
	p(".SH SEE ALSO\nhttps://github.com/zyvorai/zyvor\\-setura\\-gateway\n")
	_, err := io.WriteString(w, b.String())
	return err
}
